node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const schema = db.prepare('SELECT sql FROM sqlite_master WHERE name=?').get(t.name);
  console.log(schema.sql);
  console.log();
}
" 2>/dev/null || node -e "
const sqlite3 = require('sqlite3').verbose();
const db = new sqlite3.Database('/workspace/world.db');
db.all(\"SELECT name, sql FROM sqlite_master WHERE type='table'\", (err, rows) => {
  if (err) { console.error(err); return; }
  rows.forEach(r => console.log(r.name, r.sql));
  db.close();
});
" 2>/dev/null || echo "No node sqlite module found"
